export type DomainId = "htert" | "foxo3" | "sirt1" | "bdnf" | "creb" | "psd95";
export type ConstructId = "cascade" | "superintel";
export type LinkerId =
  | "gs4" | "gs8" | "gs12" | "gs20" | "ggr1" | "ggr3" | "ggr4" | "gsp" | "gse" | "gsr" | "hybrid" | "lowagg" | "ultra";
export type HostId = "ecoli" | "pichia" | "human";

export interface Domain {
  id: DomainId;
  name: string;
  uniprot: string;
  range: string;
  seq: string;
  tone: "a" | "b" | "c";
}

export interface Construct {
  id: ConstructId;
  name: string;
  domains: DomainId[];
}

export interface Linker {
  id: LinkerId;
  name: string;
  sequence: string;
}

