export const HIS = "HHHHHH";
export const TEV = "ENLYFQG";

export function assembleFusion(construct: Construct, linker: Linker): {
  seq: string;
  blocks: { id: string; seq: string; kind: "domain" | "linker" | "tag" }[];
} {
  const blocks: { id: string; seq: string; kind: "domain" | "linker" | "tag" }[] = [];
  construct.domains.forEach((id, i) => {
    const d = DOMAINS[id];
    blocks.push({ id: d.id, seq: d.seq, kind: "domain" });
    if (i < construct.domains.length - 1) {
      blocks.push({ id: `lnk-${i}`, seq: linker.sequence, kind: "linker" });
    }
  });
  blocks.push({ id: "tev", seq: TEV, kind: "tag" });
  blocks.push({ id: "his", seq: HIS, kind: "tag" });
  return { seq: blocks.map((b) => b.seq).join(""), blocks };
}
